'use strict';

// MODULES //

var objectKeys = require( '@stdlib/utils/keys' );
var map = require( '@stdlib/array/base/map' );
var join = require( '@stdlib/array/base/join' );
var cellID = require( './cell_id.js' );
var canonical = require( './canonical.js' );


// VARIABLES //

var FIELDS = [
	[ 'alt', 'alt' ],
	[ 'classification', 'classification' ],
	[ 'format', 'format' ],
	[ 'label', 'label' ],
	[ 'lang', 'authored_language' ],
	[ 'language', 'language' ],
	[ 'meta', 'fence_meta' ],
	[ 'payloadHash', 'payload_hash' ],
	[ 'role', 'role' ],
	[ 'semanticHash', 'semantic_hash' ],
	[ 'semanticKey', 'semantic_key' ],
	[ 'sourceHash', 'source_hash' ],
	[ 'sourceStyle', 'source_style' ]
];


// FUNCTIONS //

/**
* Splits a value into notebook lines without changing its content.
*
* @private
* @param {string} value - source
* @returns {Array} source lines
*/
function lines( value ) {
	var out;

	if ( value === '' ) {
		return [];
	}
	out = value.match( /[^\n]*\n|[^\n]+$/g );
	return out || [];
}

/**
* Returns cell metadata for a semantic container.
*
* @private
* @param {Object} node - container
* @returns {Object} metadata record
*/
function containerRecord( node ) {
	return {
		'id': node.id,
		'role': node.role,
		'semantic_key': node.semanticKey,
		'tree_hash': node.treeHash,
		'type': node.type
	};
}

/**
* Returns cell metadata for a semantic node.
*
* @private
* @param {Object} node - semantic node
* @param {boolean} provenance - boolean indicating whether to include provenance
* @returns {Object} metadata record
*/
function nodeRecord( node, provenance ) {
	var out;
	var f;
	var i;

	out = {
		'id': node.id,
		'type': node.type
	};

	for ( i = 0; i < FIELDS.length; i++ ) {
		f = FIELDS[ i ];
		if ( node[ f[ 0 ] ] !== void 0 ) {
			out[ f[ 1 ] ] = canonical( node[ f[ 0 ] ] );
		}
	}
	if ( node.execution ) {
		out.execution = canonical( node.execution );
	}
	if ( node.directiveRefs ) {
		out.directive_refs = node.directiveRefs.slice();
	}
	if ( provenance ) {
		out.source = canonical( node.source );
	}
	return out;
}

/**
* Copies extra stdlib metadata fields.
*
* @private
* @param {Object} target - target object
* @param {Object} extra - extra fields
* @returns {void}
*/
function copyExtra( target, extra ) {
	var keys;
	var i;

	keys = objectKeys( extra || {} );
	for ( i = 0; i < keys.length; i++ ) {
		target[ keys[ i ] ] = canonical( extra[ keys[ i ] ] );
	}
}


// MAIN //

/**
* Creates a notebook cell.
*
* @private
* @param {string} type - cell type
* @param {string} value - source
* @param {Array} nodes - contributing semantic nodes
* @param {Array} containers - semantic container stack
* @param {Object} state - conversion state
* @param {Object} [extra] - extra stdlib metadata
* @param {Array} [tags] - Jupyter tags
* @throws {Error} source splitting changed cell content
* @returns {Object} notebook cell
*/
function createCell( type, value, nodes, containers, state, extra, tags ) {
	var provenance;
	var metadata;
	var records;
	var stdlib;
	var cell;
	var ids;
	var i;

	provenance = state.options.includeProvenance;
	records = [];
	ids = [];
	for ( i = 0; i < nodes.length; i++ ) {
		ids.push( nodes[ i ].id );
		records.push( nodeRecord( nodes[ i ], provenance ) );
	}
	stdlib = {
		'containers': map( containers, containerRecord ),
		'semantic_nodes': records
	};
	copyExtra( stdlib, extra );

	metadata = {
		'stdlib': stdlib
	};
	if ( tags && tags.length ) {
		metadata.tags = tags.slice();
	}
	cell = {
		'cell_type': type,
		'id': cellID( type, ids, state.ids ),
		'metadata': metadata,
		'source': lines( value )
	};
	if ( type === 'code' ) {
		cell.execution_count = null;
		cell.outputs = [];
	}
	if ( join( cell.source, '' ) !== value ) {
		throw new Error( 'internal error. Notebook source splitting changed cell content.' );
	}
	return cell;
}


// EXPORTS //

module.exports = createCell;
